  assign row_b[62] = 1'b0;
  assign ksa_a = {1'b0, row_a};
  assign ksa_b = {1'b0, row_b};

  ksa #(.WIDTH(64)) ksa1 (
    .a(ksa_a),
    .b(ksa_b),
    .c_in(1'b0),
    .sum(final_sum),
    .c_out(final_carry)
  );

  assign product[63:1] = final_sum[62:0];

endmodule

module fa (
    input logic a,
    input logic b,
    input logic c_in,
    output logic sum,
    output logic c_out
);
  assign sum = a ^ b ^ c_in;
  assign c_out = (a & b) | ((a ^ b) & c_in);
endmodule
